import { Component, OnInit } from '@angular/core';
import { ActivatedRoute, Router } from '@angular/router';
import { UserService } from 'src/app/services/emis/user.service';

@Component({
  selector: 'app-samplecooming',
  templateUrl: './samplecooming.page.html',
  styleUrls: ['./samplecooming.page.scss'],
})
export class SamplecoomingPage implements OnInit {
  routeData: any;
  title: any;

  constructor(private router: Router, private userService: UserService,
    private route: ActivatedRoute) { }

  ngOnInit() {
  }

  ionViewDidEnter() {
    //debugger
    this.routeData = this.route.snapshot;
    this.title = this.routeData.queryParams.title;
  }

  goToBack() {
      this.router.navigate(['/tabs/cwsn/dashboard']);
  }

}
